/** Real production windows/IPC/renderers, isolated data and no external service calls. */
import {app,BrowserWindow,protocol,session,screen} from 'electron';
import {cp,mkdir,readFile,writeFile} from 'node:fs/promises';
import path from 'node:path';
import assert from 'node:assert/strict';
import {registerIpc} from '../../src/main/ipc';
import * as Windows from '../../src/main/windows';
import * as Rooms from '../../src/main/rooms/rooms';
import * as Visibility from '../../src/main/desktop-visibility';
import {wireRoomPetDisplay,setRoomDisplayMode} from '../../src/main/rooms/room-pet-display';
import {getCharacter} from '../../src/main/characters';
const root=process.env.QBOT_QA_ROOT!,output=path.join(root,'.superpowers/visibility-preview');
app.setPath('userData',process.env.QBOT_QA_DATA!);
protocol.registerSchemesAsPrivileged([{scheme:'qbot-asset',privileges:{stream:true,supportFetchAPI:true,bypassCSP:true}}]);
const wait=(ms:number)=>new Promise(r=>setTimeout(r,ms));
const js=(w:BrowserWindow,s:string)=>w.webContents.executeJavaScript(s);
async function until(fn:()=>Promise<unknown>|unknown,label:string){for(let i=0;i<150;i++){if(await fn())return;await wait(80);}throw Error('timeout: '+label);}
app.whenReady().then(async()=>{try{
 await mkdir(output,{recursive:true});const chars=path.join(app.getPath('userData'),'characters');await mkdir(chars,{recursive:true});
 for(const id of ['host','guest','second'])await cp(path.join(root,'app/resources/presets/mascot'),path.join(chars,id),{recursive:true});
 await writeFile(path.join(app.getPath('userData'),'config.json'),JSON.stringify({activeCharacter:'host',nickname:'可见性测试',roomsChatConsent:true,voiceEnabled:false,freeMode:false,arkApiKey:'QA-NOT-A-KEY',gptImageApiKey:'QA-NOT-A-KEY'}));
 session.defaultSession.webRequest.onBeforeRequest({urls:['http://*/*','https://*/*']},(_r,cb)=>cb({cancel:true}));
 protocol.handle('qbot-asset',async req=>{const u=new URL(req.url),file=path.resolve(chars,u.hostname,decodeURIComponent(u.pathname).slice(1));if(!file.startsWith(chars+path.sep))return new Response(null,{status:403});try{return new Response(await readFile(file),{headers:{'Content-Type':file.endsWith('.webm')?'video/webm':'image/png'}});}catch{return new Response(null,{status:404});}});
 registerIpc();Rooms.setLoungePush(Windows.pushToLounge);wireRoomPetDisplay();
 const pet=Windows.createPetWindow();Windows.setPetScale(1);Windows.broadcastCharacterActivated((await getCharacter('host'))!);
 await until(()=>js(pet,'!!document.querySelector(".hud-hide")&&!document.body.classList.contains("desktop-loading")'),'host toolbar');
 const area=screen.getDisplayMatching(pet.getBounds()).workArea;Windows.movePetWindow(area.x+80,area.y+180);
 await until(()=>BrowserWindow.getAllWindows().some(w=>w.webContents.getURL().includes('/pet-hint/')&&w.isVisible()),'exterior wish');
 const hint=BrowserWindow.getAllWindows().find(w=>w.webContents.getURL().includes('/pet-hint/'))!;
 const hp=hint.getBounds(),pp=pet.getBounds();assert.ok(hp.x+hp.width<=pp.x||hp.x>=pp.x+pp.width||hp.y+hp.height<=pp.y||hp.y>=pp.y+pp.height);
 await writeFile(path.join(output,'exterior-wish.png'),(await hint.webContents.capturePage()).toPNG());
 await js(hint,'document.querySelector("#dismiss").click()');await until(()=>!hint.isVisible(),'dismiss wish');
 pet.webContents.reload();await until(()=>js(pet,'!!document.querySelector(".hud-hide")&&!document.body.classList.contains("desktop-loading")'),'reload reminder');await wait(700);assert.equal(hint.isVisible(),false);
 await Rooms.startTestRoom();await Rooms.inviteTestGuest('guest');
 const peer=Windows.getRoomPetWindow('test:guest')!;
 await until(()=>js(peer,'!!document.querySelector(".peer-controls")&&!document.body.classList.contains("desktop-loading")'),'peer controls');
 await js(peer,`document.getElementById('stage').dispatchEvent(new PointerEvent('pointerenter'));`);
 await until(()=>js(peer,'!document.querySelector(".peer-controls").hidden'),'hover controls');
 await js(peer,`document.querySelector('[aria-label="互动"]').click()`);
 await until(()=>js(peer,'!document.querySelector(".peer-wheel").hidden'),'interaction picker');
 assert.equal(await js(peer,'document.querySelectorAll(".peer-wheel button").length'),8);
 assert.ok(await js(peer,'document.querySelectorAll(".peer-wheel button:disabled").length')>0);
 await writeFile(path.join(output,'peer-controls.png'),(await peer.webContents.capturePage()).toPNG());
 await js(peer,`document.querySelector('[aria-label="送小心心"]').click()`);
 await until(()=>js(peer,'document.querySelector(".peer-feedback").textContent.includes("开始")'),'test interaction');
 await js(peer,`document.querySelector('[aria-label="在我的桌面隐藏"]').click()`);
 await until(()=>js(peer,'document.body.classList.contains("member-hidden")'),'single peer hides');
 assert.equal(peer.isVisible(),true);assert.equal(await js(peer,'getComputedStyle(document.getElementById("stage")).display'),'none');
 assert.equal(await js(peer,'getComputedStyle(document.querySelector(".peer-controls")).display'),'block');
 await js(peer,'document.querySelector(".peer-hide").click()');await until(()=>!Visibility.memberHidden('test:guest'),'retained eye restores');
 await js(peer,'document.querySelector(".peer-hide").click()');await until(()=>Visibility.memberHidden('test:guest'),'hide again');
 assert.ok(Visibility.memberHidden('test:guest'));
 Rooms.removeTestGuest('test:guest');await Rooms.inviteTestGuest('guest');
 const rejoined=Windows.getRoomPetWindow('test:guest')!;await until(()=>rejoined.isVisible(),'rejoined toolbar visible');await until(()=>js(rejoined,'document.body.classList.contains("member-hidden")'),'rejoined actor hidden');assert.equal(rejoined.isVisible(),true);assert.equal(await js(rejoined,'getComputedStyle(document.getElementById("stage")).display'),'none');
 const social=Windows.createLoungeWindow();await until(()=>js(social,'!!document.querySelector("[data-page=room]")'),'social');
 await js(social,`document.querySelector('[data-page="room"]').click()`);
 await until(()=>js(social,'[...document.querySelectorAll("#members button")].some(b=>b.textContent==="显示在桌面")'),'member restore');
 await js(social,`[...document.querySelectorAll('#members button')].find(b=>b.textContent==='显示在桌面').click()`);
 await until(()=>rejoined.isVisible(),'restore one member');
 await until(()=>js(rejoined,'[...document.querySelectorAll("video")].some(v=>!v.paused&&v.currentTime>0)'),'restored peer playback');
 Windows.displayDesktopSign('测试留言');const bubble=Windows.showBubbleWindow();
 await js(pet,`document.querySelector('.hud-garden').click()`);await wait(900);
 Visibility.setMemberHidden('test:guest',true);
 await js(pet,`document.querySelector('.hud-hide').click()`);
 await until(()=>Visibility.desktopHidden()&&js(pet,'document.body.classList.contains("desktop-hidden")'),'global hide');
 assert.equal(pet.isVisible(),true);assert.equal(social.isVisible(),false);assert.equal(rejoined.isVisible(),false);assert.equal(bubble.isVisible(),false);
 assert.equal(await js(pet,'getComputedStyle(document.getElementById("stage")).display'),'none');
 assert.equal(await js(pet,'getComputedStyle(document.querySelector("#pet-hud")).visibility'),'visible');
 assert.equal(pet.webContents.isAudioMuted(),true);
 await writeFile(path.join(output,'hidden-toolbar.png'),(await pet.webContents.capturePage()).toPNG());
 Windows.showBubbleWindow();Windows.displayDesktopSign('不可冒出的牌子');await Rooms.inviteTestGuest('second');await wait(700);
 assert.equal(Windows.getRoomPetWindow('test:second')!.isVisible(),false);assert.equal(bubble.isVisible(),false);
 const late=new BrowserWindow({show:false});late.show();assert.equal(late.isVisible(),false);
 await js(pet,`document.querySelector('.hud-weather').click()`);await until(()=>BrowserWindow.getAllWindows().some(w=>w.webContents.getURL().includes('view=weather')&&w.isVisible()),'manual panel while hidden');
 // Reapplying hide also dismisses explicitly opened panels.
 Visibility.setDesktopHidden(true);assert.equal(BrowserWindow.getAllWindows().filter(w=>w!==pet&&w.isVisible()).length,0);
 await js(pet,`document.querySelector('.hud-hide').click()`);await until(()=>!Visibility.desktopHidden(),'restore all');
 assert.equal(rejoined.isVisible(),true);assert.equal(await js(rejoined,'getComputedStyle(document.getElementById("stage")).display'),'none');Visibility.setMemberHidden('test:guest',false);assert.equal(rejoined.isVisible(),true);assert.equal(social.isVisible(),false);late.show();assert.equal(late.isVisible(),false);assert.equal(bubble.isVisible(),false);
 const a=screen.getDisplayMatching(pet.getBounds()).workArea;
 Windows.movePetWindow(a.x,a.y+100);const before=pet.getSize();
 assert.equal(await js(pet,'window.qbot.desktop.drop()'),true);
 await until(()=>js(pet,'document.body.dataset.peek==="left"'),'left peek');
 assert.deepEqual(pet.getSize(),before);assert.equal(await js(pet,'getComputedStyle(document.getElementById("pet-hud")).visibility'),'hidden');
 await wait(500);await writeFile(path.join(output,'peek-left.png'),(await pet.webContents.capturePage()).toPNG());
 await js(pet,'window.qbot.desktop.toggle()');await until(()=>Visibility.desktopHidden(),'hide while peeking');assert.equal(await js(pet,'getComputedStyle(document.getElementById("pet-hud")).visibility'),'visible');
 await js(pet,'window.qbot.desktop.toggle()');await until(()=>!Visibility.desktopHidden(),'restore peek');assert.equal(Visibility.desktopSnapshot(pet).peek,'left');
 pet.webContents.sendInputEvent({type:'mouseDown',x:20,y:110,button:'left',clickCount:1});
 pet.webContents.sendInputEvent({type:'mouseUp',x:20,y:110,button:'left',clickCount:1});
 await until(()=>!Visibility.desktopSnapshot(pet).peek,'click head to unpeek');
 Windows.movePetWindow(a.x,a.y+100);await js(pet,'window.qbot.desktop.drop()');await wait(100);
 pet.webContents.sendInputEvent({type:'mouseDown',x:20,y:110,button:'left',clickCount:1});
 pet.webContents.sendInputEvent({type:'mouseMove',x:100,y:140,button:'left'});await wait(100);
 pet.webContents.sendInputEvent({type:'mouseUp',x:100,y:140,button:'left',clickCount:1});
 await until(()=>!Visibility.desktopSnapshot(pet).peek,'drag head out');
 assert.deepEqual(pet.getSize(),before);
 Windows.movePetWindow(a.x+a.width-before[0],a.y+100);assert.equal(await js(pet,'window.qbot.desktop.drop()'),true);assert.equal(Visibility.desktopSnapshot(pet).peek,'right');
 await wait(500);await writeFile(path.join(output,'peek-right.png'),(await pet.webContents.capturePage()).toPNG());
 Visibility.setDesktopHidden(true);pet.webContents.reload();await until(()=>js(pet,'!!document.querySelector(".hud-hide")&&document.body.classList.contains("desktop-hidden")'),'hidden reload');
 assert.equal(await js(pet,'getComputedStyle(document.getElementById("stage")).display'),'none');
 assert.equal(BrowserWindow.getAllWindows().filter(w=>w!==pet&&w.isVisible()).length,0);
 // Chromium flex rounding can exceed the viewport by a fraction of a DIP.
 Windows.setPetScale(.5);await wait(300);
 assert.equal(await js(pet,'(()=>{const r=document.querySelector(".hud-hide").getBoundingClientRect();return r.left>=-1&&r.right<=innerWidth+1&&r.width>0})()'),true);
 Windows.setPetScale(1);
 Visibility.setDesktopHidden(false);Visibility.setWindowPeek(pet,null);await setRoomDisplayMode('room');
 await until(()=>Windows.getRoomWindow()?.isVisible()&&!pet.isVisible(),'room display');
 Visibility.setDesktopHidden(true);await until(()=>pet.isVisible(),'toolbar available from room mode');
 assert.equal(Windows.getRoomWindow()?.isVisible(),false);
 await js(pet,'window.qbot.desktop.toggle()');await until(()=>Windows.getRoomWindow()?.isVisible()&&!pet.isVisible(),'restore room presentation');
 console.log('PASS: real renderer toolbar, 8 interaction choices and locks, local heart, member hide/rejoin/restore, all-window hide, late windows, manual panel, mute, no stale bubble restore, both screen edges, fixed size, hidden reload. '+output);
 app.exit(0);
}catch(error){console.error(error);app.exit(1);}});
